ALTER TABLE "work"."card_types" ADD COLUMN "icon" text DEFAULT 'checkbox' NOT NULL;--> statement-breakpoint
ALTER TABLE "work"."card_types" ADD COLUMN "color" text DEFAULT 'gray' NOT NULL;--> statement-breakpoint
-- The types spaces already have take the look `lookOf` gives their name (cards/card-type.schemas.ts).
UPDATE "work"."card_types" SET "icon" = CASE lower(trim("name")) WHEN 'bug' THEN 'bug' WHEN 'tarefa' THEN 'checkbox' WHEN 'história' THEN 'bookmark' WHEN 'epic' THEN 'bolt' WHEN 'épico' THEN 'bolt' WHEN 'spike' THEN 'bulb' WHEN 'subtarefa' THEN 'subtask' WHEN 'ideia' THEN 'bulb' WHEN 'requisição' THEN 'file' WHEN 'oportunidade' THEN 'target' WHEN 'data' THEN 'database' WHEN 'protótipo' THEN 'palette' WHEN 'solicitação' THEN 'message' WHEN 'incidente' THEN 'flag' ELSE 'checkbox' END, "color" = CASE lower(trim("name")) WHEN 'bug' THEN 'red' WHEN 'tarefa' THEN 'blue' WHEN 'história' THEN 'green' WHEN 'epic' THEN 'violet' WHEN 'épico' THEN 'violet' WHEN 'spike' THEN 'yellow' WHEN 'subtarefa' THEN 'teal' WHEN 'ideia' THEN 'yellow' WHEN 'requisição' THEN 'blue' WHEN 'oportunidade' THEN 'orange' WHEN 'data' THEN 'violet' WHEN 'protótipo' THEN 'pink' WHEN 'solicitação' THEN 'teal' WHEN 'incidente' THEN 'red' ELSE 'gray' END;
